import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getMyListings } from '../services/api';
import styles from './AccountPage.module.css';

export default function AccountPage() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [listings, setListings] = useState([]);
  const [loading, setLoading]   = useState(true);
  const [tab, setTab]           = useState('profile');

  useEffect(() => {
    if (!user) { navigate('/login'); return; }
    getMyListings()
      .then(({ data }) => setListings(data.properties || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [user, navigate]);

  const handleLogout = () => { logout(); navigate('/'); };

  if (!user) return null;

  return (
    <div className={`container ${styles.wrap}`}>
      <div className={styles.inner}>
        {/* Sidebar */}
        <aside className={styles.sidebar}>
          <div className={styles.avatarWrap}>
            {user.photo
              ? <img src={user.photo} alt={user.name} className={styles.avatar} />
              : <div className={styles.avatarInitials}>{user.name?.[0]?.toUpperCase()}</div>
            }
            <div className={styles.userName}>{user.name}</div>
            <div className={styles.userEmail}>{user.email}</div>
          </div>
          <nav className={styles.nav}>
            <button className={`${styles.navItem} ${tab === 'profile'  ? styles.navActive : ''}`} onClick={() => setTab('profile')}>Profile</button>
            <button className={`${styles.navItem} ${tab === 'listings' ? styles.navActive : ''}`} onClick={() => setTab('listings')}>My Listings</button>
            <Link to="/saved"  className={styles.navItem}>Saved Properties</Link>
            <Link to="/post-property" className={styles.navItem}>+ Post Property</Link>
            <button className={`${styles.navItem} ${styles.logout}`} onClick={handleLogout}>Sign Out</button>
          </nav>
        </aside>

        {/* Content */}
        <main className={styles.main}>
          {tab === 'profile' && (
            <div className={styles.card}>
              <h2 className={styles.cardTitle}>My Profile</h2>
              <div className={styles.profileRow}><span className={styles.profileKey}>Name</span><span className={styles.profileVal}>{user.name}</span></div>
              <div className={styles.profileRow}><span className={styles.profileKey}>Email</span><span className={styles.profileVal}>{user.email}</span></div>
              <div className={styles.profileRow}><span className={styles.profileKey}>Phone</span><span className={styles.profileVal}>{user.phone || '—'}</span></div>
            </div>
          )}

          {tab === 'listings' && (
            <div>
              <div className={styles.listingsHeader}>
                <h2 className={styles.cardTitle}>My Listings</h2>
                <Link to="/post-property" className={styles.postBtn}>+ Add New</Link>
              </div>
              {loading ? <div className={styles.loading}>Loading…</div>
                : listings.length === 0 ? (
                  <div className={styles.emptyListings}>
                    <div style={{ fontSize: 40 }}>🏠</div>
                    <div className={styles.emptyTitle}>No listings yet</div>
                    <Link to="/post-property" className={styles.postBtn2}>Post Your First Property</Link>
                  </div>
                ) : (
                  <div className={styles.listingsList}>
                    {listings.map(p => (
                      <div key={p.id || p._id} className={styles.listingItem}>
                        <img
                          src={p.image || (p.images?.[0]) || 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=400&q=70'}
                          alt={p.title}
                          className={styles.listingImg}
                        />
                        <div className={styles.listingInfo}>
                          <div className={styles.listingTitle}>{p.title}</div>
                          <div className={styles.listingLoc}>{p.location}</div>
                          <div className={styles.listingPrice}>{p.price}</div>
                          <span className={`${styles.statusBadge} ${styles['status_' + (p.approvalStatus || p.status || 'pending')]}`}>
                            {p.approvalStatus || p.status || 'pending'}
                          </span>
                        </div>
                        <Link to={`/property/${p.id || p._id}`} className={styles.viewLink}>View →</Link>
                      </div>
                    ))}
                  </div>
                )
              }
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
